/* قطّة الربع — a dependency-free, portable monthly ledger. */
'use strict';
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',receipt:'<path d="M4 3l2 1 2-1 2 1 2-1 2 1 2-1 2 1 2-1v18l-2-1-2 1-2-1-2 1-2-1-2 1-2-1-2 1V3zm4 5h8M8 12h8M8 16h5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h2"/>',settings:'<path d="m9.5 3-.5 2-2 1-2-.5-2 3 1.5 1.5v3L3 14.5l2 3 2-.5 2 1 .5 3h5l.5-3 2-1 2 .5 2-3-1.5-1.5v-3L21 8.5l-2-3-2 .5-2-1-.5-2z"/><circle cx="12" cy="12" r="3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3zm-4 9 3 3 5-6"/>','chevron-right':'<path d="m9 6 6 6-6 6"/>','chevron-left':'<path d="m15 6-6 6 6 6"/>','chevron-down':'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>','user-plus':'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m18-13v6m-3-3h6"/><circle cx="9" cy="7" r="4"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6m18 7h-5v4h5"/>',download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M12 3v12m-5-5 5 5 5-5"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','arrow-down':'<path d="M12 4v16m-6-6 6 6 6-6M4 4h3m10 0h3"/>','arrow-up':'<path d="M12 20V4m-6 6 6-6 6 6M4 20h3m10 0h3"/>',edit:'<path d="m16 3 5 5L8 21H3v-5L16 3zm-2 2 5 5"/>',coins:'<ellipse cx="9" cy="5" rx="6" ry="3"/><path d="M3 5v8c0 4 12 4 12 0V5M3 9c0 4 12 4 12 0m0 0c7-2 9 4 3 5m-3 0v6c4 2 8-1 8-3v-6"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.receipt}</svg>`;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('ar-SA',{maximumFractionDigits:2}).format(n);
const money=n=>`${fmt(n/100)} <span class="currency">ر.س</span>`;
const dateISO=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const currentMonth=()=>dateISO().slice(0,7);
const monthLabel=key=>new Intl.DateTimeFormat('ar-SA',{month:'long',year:'numeric',calendar:'gregory'}).format(new Date(`${key}-15T12:00:00`));
const shortDate=d=>d?new Intl.DateTimeFormat('ar-SA',{day:'numeric',month:'short',calendar:'gregory'}).format(new Date(`${d}T12:00:00`)):'';
const uid=()=>globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const config=window.QATTA_CONFIG||{};
const configured=Boolean(config.supabaseUrl&&config.supabaseKey);
let db=null,admin=false,revision=0,syncState=configured?'loading':'demo',saving=false;
let selectedMonth=currentMonth(),filter='all';
const INITIAL_SETTINGS=Object.freeze({name:'استراحة الربع',recipient:'حمدان (أبو ذنب)',dues:20000,transfer:''});
const INITIAL_MEMBER_NAMES=Object.freeze([
  'علي (قوقل)',
  'خالد محي',
  'بدر',
  'سالم',
  'أبو هادي (الصومعه)',
  'أحمد (أحمد فيديو)',
  'مجاد',
  'فيصل',
  'فايز',
  'حمدان (أبو ذنب)',
  'فهد',
  'مفوز'
]);
function initialMembers(){return INITIAL_MEMBER_NAMES.map((name,i)=>({id:`member-${i+1}`,name,paid:0,date:'',note:''}));}
function sampleState(){const key=currentMonth();return {version:1,demo:true,settings:{...INITIAL_SETTINGS},months:{[key]:{dues:INITIAL_SETTINGS.dues,recipient:INITIAL_SETTINGS.recipient,transfer:'',members:initialMembers(),expenses:[]}}};}
function emptyState(){return {version:1,demo:false,settings:{...INITIAL_SETTINGS},months:{}};}
let state=configured?emptyState():sampleState();
function current(){return state.months[selectedMonth];}
function totals(month=current()){const m=month||{members:[],expenses:[],dues:state.settings.dues};const target=m.members.length*m.dues,collected=m.members.reduce((n,p)=>n+p.paid,0),spent=m.expenses.filter(e=>e.paid).reduce((n,e)=>n+e.amount,0),committed=m.expenses.filter(e=>!e.paid).reduce((n,e)=>n+e.amount,0);return {target,collected,spent,committed,balance:collected-spent,remaining:target-collected,paidCount:m.members.filter(p=>p.paid>=m.dues).length,count:m.members.length,percent:target?Math.floor(collected/target*100):0};}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function render(){const m=current(),t=totals(),s=state.settings,recipient=m?.recipient||s.recipient;$('#place-name').textContent=s.name;$('#selected-month').textContent=monthLabel(selectedMonth);$('#recipient-name').textContent=recipient;$('#recipient-card-name').textContent=recipient;$('#hamdan-transfer').hidden=!/^حمدان(?:\s|$)/.test(recipient);$('#sidebar-recipient').textContent=recipient;$('#recipient-avatar').textContent=recipient[0]||'ق';$('.manager .avatar').textContent=recipient[0]||'ق';$('#demo-strip').hidden=!state.demo;$('#storage-label').textContent=({demo:'عرض تجريبي',loading:'جاري الاتصال…',online:'سجل مشترك',offline:'الاتصال متعذّر · إعادة المحاولة'})[syncState];$('#account-button').textContent=admin?'حساب المسؤول':'دخول المسؤول';$('#dues-note').textContent=`${fmt((m?.dues||s.dues)/100)} ر.س على الواحد`;$('#transfer-note').textContent=(m?m.transfer:s.transfer)||'حوّل لأمين القطّة، ثم خلّه يسجّل دفعتك هنا.';$('#progress-percent').textContent=`${fmt(t.percent)}٪`;$('#progress-fill').style.width=`${Math.min(t.percent,100)}%`;$('.progress-track').setAttribute('aria-valuenow',t.percent);$('#progress-count').textContent=`${fmt(t.paidCount)} من ${fmt(t.count)} دفعوا`;$('#progress-target').textContent=`الهدف ${fmt(t.target/100)} ر.س`;$('#progress-cheer').innerHTML=`<span>✦</span> ${t.count===0?'أول خوي ينضم، وتبدأ اللمّة.':t.percent===100?'اكتملت القطّة… بيّض الله وجيهكم!':t.percent>=70?'باقي تكّة وتكتمل اللمّة!':'قطّة ورا قطّة، والبركة في الربع.'}`;$('#banner-title').textContent=t.count&&t.percent===100?'القطّة اكتملت. الوناسة تبدأ!':'الجمعة الحلوة تبدأ بقطّة.';$('#member-count').textContent=fmt(t.count);$('#nav-count').textContent=fmt(t.count);$('#paid-count').textContent=fmt(t.paidCount);$('#pending-count').textContent=fmt(t.count-t.paidCount);
const cards=[['اللي جمعناه',t.collected,'coins','',`${fmt(t.paidCount)} من الربع بيّضوا الوجه`],['القطّة المتبقية',t.remaining,'clock','orange','ننتظر الباقين، وكلهم أهل خير'],['اللي صرفناه',t.spent,'arrow-up','lilac','مصاريف مدفوعة من قطّة الشهر'],['الباقي في الصندوق',t.balance,'wallet','green','المحصّل ناقص المصاريف المدفوعة']];$('#stats').innerHTML=cards.map(([label,value,i,c,sub])=>`<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${c}">${icon(i)}</span></div><div class="stat-number ${value<0?'negative':''}">${money(value)}</div><div class="stat-caption">${sub}</div></article>`).join('');
const members=(m?.members||[]).filter(p=>filter==='all'||(filter==='paid'?p.paid>=m.dues:p.paid<m.dues));$('#member-rows').innerHTML=members.length?members.map((p,i)=>{const paid=p.paid>=m.dues,partial=p.paid>0&&!paid;return `<tr><td><div class="member-cell"><span class="member-avatar color-${i%4}">${esc(p.name[0])}</span><div><div class="member-name">${esc(p.name)}</div><div class="member-meta">${paid?`وصلت ${shortDate(p.date)}`:partial?'وصل بعض القطّة':'مكانك محفوظ في المجلس'}</div></div></td><td class="amount-cell">${fmt(m.dues/100)} <small>ر.س</small></td><td><span class="status ${paid?'paid':partial?'partial':'pending'}">${icon(paid?'check':'clock')}${paid?'دفع ووفّى':partial?`دفع ${fmt(p.paid/100)}`:'ننتظر حوّلته'}</span></td><td><button class="row-action" data-action="payment" data-id="${esc(p.id)}" aria-label="${paid?'تعديل دفعة':'تسجيل دفعة'} ${esc(p.name)}">${paid?icon('edit'):'تسجيل'}</button></td></tr>`;}).join(''):`<tr><td colspan="4"><div class="empty-state"><strong>${!m?'دفتر جديد، ولمّة جديدة':t.count?'كلهم في القلب':'المجلس ينتظر ربعه'}</strong>${!m?'افتح دفتر الشهر لبدء تسجيل القطّة.':t.count?'ما فيه أحد بهذه الحالة.':'أضف أسماء الربع وابدأ تسجيل الدفعات.'}${!m?'<br><button class="outline-button" data-action="create-month">فتح دفتر الشهر</button>':!t.count?'<br><button class="outline-button" data-action="member">إضافة أول خوي</button>':''}</div></td></tr>`;
document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));renderExpenses(m,t);document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));document.querySelectorAll('[data-action="member"],.small-button[data-action="expense"],[data-action="settings"],.row-action,.light-button,[data-action="create-month"]').forEach(el=>el.hidden=configured&&!admin);document.querySelectorAll('.expense-action').forEach(el=>{el.disabled=configured&&!admin;el.classList.toggle('read-only',configured&&!admin);});}
function renderExpenses(m,t){const categories={rent:'🏡',bills:'💡',supplies:'☕',other:'🧾'};$('#expense-list').innerHTML=m?.expenses.length?m.expenses.map(e=>`<article class="expense-item"><div class="expense-item-top"><span class="expense-icon">${categories[e.category]||'🧾'}</span><div><h3>${esc(e.title)}</h3><small>${e.paid?'تاريخ الصرف':'موعد الالتزام'} · ${shortDate(e.date)}</small></div></div><div class="expense-item-bottom"><span class="expense-amount">${money(e.amount)}</span><button class="expense-action" data-action="expense" data-id="${esc(e.id)}" aria-label="تعديل ${esc(e.title)}"><span class="status ${e.paid?'paid':'pending'}">${e.paid?'مدفوع':'بانتظار الدفع'}</span>${icon('chevron-left')}</button></div></article>`).join(''):'<div class="empty-state">الصندوق مرتاح… ما سجلنا التزامات لهذا الشهر.</div>';$('#expenses-total').innerHTML=`<span>التزامات غير مدفوعة: <strong>${fmt(t.committed/100)} ر.س</strong></span><span>بعد سدادها يتبقى: <strong class="${t.balance-t.committed<0?'negative':''}">${fmt((t.balance-t.committed)/100)} ر.س</strong></span>`;}
function validMonth(k){return typeof k==='string'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(k)&&k>='2000-01'&&k<='2100-12';}
function validDate(d){return typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(Date.parse(`${d}T12:00:00Z`))&&new Date(`${d}T12:00:00Z`).toISOString().slice(0,10)===d;}
function cleanText(v,max=80,required=true){if(typeof v!=='string'||v.length>max||(required&&!v.trim()))throw Error('راجع النص المدخل؛ الاسم مطلوب وبحد أقصى ٨٠ حرفًا.');return v.trim();}
function cents(value,allowZero=false){const normalized=String(value).trim().replace(/[٠-٩]/g,n=>'٠١٢٣٤٥٦٧٨٩'.indexOf(n)).replace(/[۰-۹]/g,n=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(n)).replace('٫','.');if(!/^\d{1,6}(\.\d{1,2})?$/.test(normalized))throw Error('اكتب مبلغًا صحيحًا، وبحد أقصى منزلتين عشريتين.');const n=Math.round(Number(normalized)*100);if(n<(allowZero?0:1)||n>10000000)throw Error('المبلغ يجب أن يكون بين ريال واحد أو كسوره و١٠٠٬٠٠٠ ريال.');return n;}
function validateState(input){if(!input||input.version!==1||typeof input.demo!=='boolean'||!input.settings||!input.months||Array.isArray(input.months))throw Error('هذه ليست نسخة صالحة من دفتر قطّة الربع.');const validMoney=(n,zero=false)=>Number.isSafeInteger(n)&&n>=(zero?0:1)&&n<=10000000;const s=input.settings;cleanText(s.name);cleanText(s.recipient);cleanText(s.transfer,500,false);if(!validMoney(s.dues))throw Error('مبلغ القطّة غير صالح.');const months=Object.entries(input.months);if(months.length>600)throw Error('عدد الشهور يتجاوز حد الدفتر.');for(const [key,m] of months){if(!validMonth(key)||!m||!validMoney(m.dues)||!Array.isArray(m.members)||m.members.length>200||!Array.isArray(m.expenses)||m.expenses.length>500)throw Error('بيانات الشهر غير صالحة.');cleanText(m.recipient);cleanText(m.transfer,500,false);const ids=new Set();for(const p of m.members){cleanText(p.id,100);cleanText(p.name);cleanText(p.note,300,false);if(ids.has(p.id)||!validMoney(p.paid,true)||p.paid>m.dues||(p.paid>0&&(!validDate(p.date)||p.date.slice(0,7)!==key))||(p.paid===0&&p.date!==''))throw Error('بيانات إحدى الدفعات غير صالحة.');ids.add(p.id);}const eids=new Set();for(const e of m.expenses){cleanText(e.id,100);cleanText(e.title);if(eids.has(e.id)||!validMoney(e.amount)||!validDate(e.date)||typeof e.paid!=='boolean'||!['rent','bills','supplies','other'].includes(e.category))throw Error('بيانات أحد الالتزامات غير صالحة.');eids.add(e.id);}}if(JSON.stringify(input).length>1500000)throw Error('حجم الدفتر أكبر من المسموح.');return input;}
function canEdit(){if(saving){toast('جارٍ حفظ التعديل، لحظة واحدة.');return false;}if(!configured)return true;if(syncState!=='online'){toast('انتظر اتصال السجل قبل التعديل.');return false;}if(!admin){accountDialog();return false;}return true;}
async function commit(change,message){if(saving)throw Error('جارٍ حفظ التعديل السابق.');if(configured&&(!admin||syncState!=='online'))throw Error('يلزم اتصال بالسجل ودخول المسؤول.');const next=structuredClone(state);change(next);validateState(next);saving=true;try{if(configured){next.demo=false;const {data,error}=await db.rpc('save_qatta',{expected_revision:revision,new_data:next});if(error){if(error.message?.includes('QATTA_CONFLICT')){await refresh();throw Error('تغيّر السجل من جهاز آخر. راجع آخر البيانات ثم أعد التعديل.');}if(error.code==='42501'||error.status===401){admin=false;render();throw Error('انتهت الجلسة أو لا توجد صلاحية. ادخل بحساب المسؤول مجددًا.');}throw Error('لم يُحفظ التعديل. تحقّق من الاتصال وحاول مجددًا.');}const row=Array.isArray(data)?data[0]:data;if(!row)throw Error('لم يُحفظ التعديل. تحقق من صلاحية المسؤول.');state=validateState(row.data);revision=row.revision;}else state=next;render();if(message)toast(message);}finally{saving=false;}}
function openDialog(title,html,onSubmit){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;const dialog=$('#app-dialog');if(!dialog.open)dialog.showModal();const form=$('#dialog-content form');if(form&&onSubmit)form.addEventListener('submit',async event=>{event.preventDefault();const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const err=form.querySelector('.form-error');if(err)err.textContent='';try{await onSubmit(new FormData(form),form);}catch(e){if(err)err.textContent=e.message||'تعذّر تنفيذ الطلب، حاول مجددًا.';else toast('تعذّر تنفيذ الطلب.');}finally{buttons.forEach(b=>b.disabled=false);}});}
function closeDialog(){$('#app-dialog').close();}
function field(label,name,value='',attrs=''){return `<label class="field">${label}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;}
const errorSlot='<p class="form-error" role="alert"></p>';
const formActions=(label='حفظ')=>`${errorSlot}<div class="form-actions"><button class="primary-button" type="submit">${label}</button><button class="outline-button" type="button" data-action="close-dialog">إلغاء</button></div>`;
const monthDate=()=>selectedMonth===currentMonth()?dateISO():`${selectedMonth}-01`;
function paymentDialog(id){if(!canEdit())return;const m=current();if(!m){createMonthDialog();return;}if(!m.members.length){memberDialog();return;}const person=m.members.find(p=>p.id===id);const options=m.members.map(p=>`<option value="${esc(p.id)}" ${p.id===(person?.id||m.members.find(x=>x.paid<m.dues)?.id)?'selected':''}>${esc(p.name)}</option>`).join('');const lastDay=new Date(Number(selectedMonth.slice(0,4)),Number(selectedMonth.slice(5)),0).getDate();openDialog(person?'دفعة الخوي':'بيّض الله وجهك!',`<p class="form-help">${monthLabel(selectedMonth)} · القطّة ${fmt(m.dues/100)} ر.س. سجّل المبلغ بعد التأكد من وصول الحوالة.</p><form class="form-grid">${person?field('اسم الخوي','name',person.name,'required maxlength="80"'):`<label class="field">الخوي<select name="person">${options}</select></label>`}<div class="form-two">${field('إجمالي ما دفعه هذا الشهر (ر.س)','paid',(person?.paid||m.dues)/100,'required inputmode="decimal" autocomplete="off"')}${field('تاريخ آخر دفعة','date',person?.date||monthDate(),`type="date" required min="${selectedMonth}-01" max="${selectedMonth}-${lastDay}"`)}</div><p class="form-help" style="margin:0">للدفعة الجزئية اكتب المبلغ المحصّل. اكتب ٠ لتصحيح دفعة مسجّلة بالخطأ.</p>${field('ملاحظة (اختياري)','note',person?.note||'','maxlength="300"')}${formActions('تأكيد الدفعة')}${person?`<button type="button" class="danger-button" data-action="remove-member" data-id="${esc(person.id)}">حذف الخوي من هذا الشهر</button>`:''}</form>`,async f=>{const target=person?.id||f.get('person'),paid=cents(f.get('paid'),true),date=paid?f.get('date'):'';if(paid>m.dues)throw Error('المبلغ أكبر من قطّة الشهر. راجع المبلغ المدخل.');if(paid&&(!validDate(date)||!date.startsWith(selectedMonth)))throw Error('اختر تاريخًا ضمن الشهر المحدد.');await commit(d=>{const p=d.months[selectedMonth].members.find(x=>x.id===target);if(!p)throw Error('الخوي غير موجود في هذا الشهر.');p.paid=paid;p.date=date;p.note=cleanText(f.get('note'),300,false);if(person)p.name=cleanText(f.get('name'));},paid===m.dues?'وصلت القطّة… بيّض الله وجهه!':'تم تحديث الدفعة.');closeDialog();});}
function memberDialog(){if(!canEdit())return;if(!current()){createMonthDialog();return;}openDialog('حيّ الله الخوي الجديد',`<p class="form-help">سينضم إلى دفتر ${monthLabel(selectedMonth)} بقطّة ${fmt(current().dues/100)} ر.س.</p><form class="form-grid">${field('الاسم أو الكنية','name','','required maxlength="80" placeholder="مثل: أبو ناصر"')}${formActions('إضافة الخوي')}</form>`,async f=>{const name=cleanText(f.get('name'));if(current().members.some(p=>p.name===name))throw Error('هذا الاسم موجود؛ أضف لقبًا يميّز الخوي.');await commit(d=>d.months[selectedMonth].members.push({id:uid(),name,paid:0,date:'',note:''}),'نوّر المجلس! تمت إضافة الخوي.');closeDialog();});}
function expenseDialog(id){if(!canEdit())return;if(!current()){createMonthDialog();return;}const e=current().expenses.find(x=>x.id===id);openDialog(e?'تعديل الالتزام':'وش يحتاج المجلس؟',`<p class="form-help">المصاريف المدفوعة تُخصم من الصندوق، والالتزامات القادمة تظهر منفصلة.</p><form class="form-grid">${field('اسم الالتزام','title',e?.title||'','required maxlength="80" placeholder="مثل: فاتورة الكهرباء"')}<div class="form-two">${field('المبلغ (ر.س)','amount',e?e.amount/100:'','required inputmode="decimal"')}${field('التاريخ','date',e?.date||monthDate(),'type="date" required')}</div><label class="field">التصنيف<select name="category">${[['rent','إيجار الاستراحة'],['bills','فواتير'],['supplies','ضيافة ومستلزمات'],['other','شيء آخر']].map(([v,l])=>`<option value="${v}" ${e?.category===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="check-field"><input type="checkbox" name="paid" ${e?.paid?'checked':''}>تم دفع المبلغ من الصندوق</label>${formActions(e?'حفظ التعديل':'إضافة الالتزام')}${e?`<button class="danger-button" type="button" data-action="remove-expense" data-id="${esc(e.id)}">حذف الالتزام</button>`:''}</form>`,async f=>{const item={id:e?.id||uid(),title:cleanText(f.get('title')),amount:cents(f.get('amount')),date:f.get('date'),category:f.get('category'),paid:f.has('paid')};if(!validDate(item.date))throw Error('اختر تاريخًا صحيحًا.');await commit(d=>{const list=d.months[selectedMonth].expenses;if(e)list[list.findIndex(x=>x.id===e.id)]=item;else list.push(item);},e?'تم تحديث الالتزام.':'انحسبت في الدفتر.');closeDialog();});}
function settingsDialog(){if(!canEdit())return;const s=state.settings,m=current();openDialog('إعدادات الاستراحة',`<p class="form-help">القطّة وأمين الصندوق يتحدثان لهذا الشهر وللشهور الجديدة؛ دفاتر الشهور الأخرى تبقى كما هي.</p><form class="form-grid">${field('اسم الاستراحة','name',s.name,'required maxlength="80"')}<div class="form-two">${field('أمين قطّة الشهر','recipient',m?.recipient||s.recipient,'required maxlength="80"')}${field('القطّة على الواحد (ر.س)','dues',(m?.dues||s.dues)/100,'required inputmode="decimal"')}</div><label class="field">بيانات التحويل (اختياري)<textarea name="transfer" rows="3" maxlength="500" placeholder="اسم البنك واسم المستفيد أو طريقة التحويل">${esc(m?m.transfer:s.transfer)}</textarea><small>تظهر هذه البيانات لكل من يفتح الصفحة.</small></label>${formActions('حفظ الإعدادات')}</form><div class="settings-backup"><h3>نسخة من دفترنا</h3><p>احتفظ بنسخة احتياطية. استيراد النسخة يستبدل الدفتر بكل شهوره.</p><div class="form-actions"><button class="outline-button" data-action="export">تنزيل نسخة</button><button class="outline-button" data-action="import">استيراد نسخة</button></div></div>`,async f=>{const dues=cents(f.get('dues'));if(m?.members.some(p=>p.paid>dues))throw Error('القطّة الجديدة أقل من دفعة مسجّلة؛ صحّح الدفعات أولًا.');await commit(d=>{d.settings={name:cleanText(f.get('name')),recipient:cleanText(f.get('recipient')),dues,transfer:cleanText(f.get('transfer'),500,false)};if(d.months[selectedMonth])Object.assign(d.months[selectedMonth],{dues,recipient:d.settings.recipient,transfer:d.settings.transfer});},'تم ترتيب أمور المجلس.');closeDialog();});}
function monthsDialog(){const entries=Object.keys(state.months).sort().reverse();openDialog('دفاتر الشهور',`<div class="month-list">${entries.length?entries.map(k=>{const t=totals(state.months[k]);return `<button class="month-entry ${k===selectedMonth?'selected':''}" data-action="select-month" data-month="${k}"><strong>${monthLabel(k)}</strong><small>${fmt(t.paidCount)} / ${fmt(t.count)} دفعوا</small></button>`;}).join(''):'<p class="form-help">ما فتحنا أول دفتر حتى الآن.</p>'}</div><form class="form-grid">${field('انتقل إلى شهر','month',selectedMonth,'type="month" min="2000-01" max="2100-12" required')}${formActions('عرض الشهر')}</form>`,async f=>{const key=f.get('month');if(!validMonth(key))throw Error('اختر شهرًا صحيحًا.');selectedMonth=key;filter='all';render();closeDialog();});}
function createMonthDialog(){if(!canEdit())return;if(current()){toast('دفتر هذا الشهر موجود بالفعل.');return;}const s=state.settings,previousKey=Object.keys(state.months).filter(k=>k<selectedMonth).sort().at(-1);openDialog('شهر جديد، وقطّة جديدة',`<p class="form-help">${monthLabel(selectedMonth)}. تبدأ الدفعات والمصاريف من الصفر.</p><form class="form-grid"><div class="form-two">${field('القطّة على الواحد (ر.س)','dues',s.dues/100,'required inputmode="decimal"')}${field('أمين القطّة','recipient',s.recipient,'required maxlength="80"')}</div>${previousKey?`<label class="check-field"><input type="checkbox" name="copy" checked>نفس الربع من ${monthLabel(previousKey)}</label>`:`<label class="check-field"><input type="checkbox" name="initial" checked>إضافة الربع (${fmt(INITIAL_MEMBER_NAMES.length)} خوي)</label>`}${formActions('فتح دفتر الشهر')}</form>`,async f=>{await commit(d=>{if(d.months[selectedMonth])throw Error('الشهر موجود بالفعل.');d.months[selectedMonth]={dues:cents(f.get('dues')),recipient:cleanText(f.get('recipient')),transfer:d.settings.transfer,members:f.has('copy')?(d.months[previousKey]?.members||[]).map(p=>({...p,paid:0,date:'',note:''})):(f.has('initial')?initialMembers():[]),expenses:[]};},'فتحنا دفتر الشهر… يا هلا بالقطّة!');closeDialog();});}
function confirmDialog(title,message,action,label='تأكيد'){openDialog(title,`<p class="form-help">${esc(message)}</p><form>${formActions(label)}</form>`,async()=>{await action();closeDialog();});}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`qatta-${state.demo?'demo-':''}${dateISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم تجهيز نسخة الدفتر للتنزيل.');}
function setupDialog(){openDialog('نبدأ قطّتنا الحقيقية',`<p class="form-help">هذه نسخة تجريبية، والتغييرات فيها مؤقتة حتى تغلق الصفحة. جاهزين للسجل المشترك؟</p><ol class="setup-steps"><li>أنشئ مشروعًا في Supabase.</li><li>نفّذ ملف إعداد قاعدة البيانات، وأضف حساب أمين القطّة.</li><li>ضع رابط المشروع ومفتاحه العلني في إعدادات الموقع.</li><li>ارفع الصفحة على GitHub Pages.</li></ol><p class="inline-notice">دليل الربط الكامل مرفق مع ملفات المشروع. بعد الربط افتح أول شهر لإضافة أسماء الربع المحفوظة، بدون أي دفعات مسبقة.</p><button class="primary-button" data-action="close-dialog">تمام، نكمّل التجربة</button>`);}
function loginEmail(value){const login=String(value??'').trim().toLowerCase();if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(login))return login;if(/^[a-z][a-z0-9_-]{2,31}$/.test(login))return `${login}@qatta.example`;throw Error('أدخل اسم المستخدم أو البريد الإلكتروني بشكل صحيح.');}
async function accountDialog(){if(!configured){setupDialog();return;}if(!db){toast('تعذّر الاتصال. اضغط حالة الاتصال للمحاولة مجددًا.');return;}if(admin){openDialog('حساب أمين القطّة',`<p class="form-help">أنت داخل بحساب المسؤول. بعد تسجيل الخروج يمكنك متابعة الدفتر دون تعديل.</p><form>${formActions('تسجيل الخروج')}</form>`,async()=>{const {error}=await db.auth.signOut();if(error)throw Error('تعذّر تسجيل الخروج. حاول مجددًا.');admin=false;render();closeDialog();toast('تم تسجيل الخروج.');});return;}openDialog('دخول أمين القطّة',`<p class="form-help">المشاهدة لكل الربع، والتعديل لأمين القطّة.</p><form class="form-grid">${field('اسم المستخدم أو البريد الإلكتروني','email','','type="text" required autocomplete="username" autocapitalize="none" spellcheck="false" dir="ltr"')}${field('كلمة المرور','password','','type="password" required autocomplete="current-password"')}${formActions('دخول المجلس')}</form>`,async f=>{const {data,error}=await db.auth.signInWithPassword({email:loginEmail(f.get('email')),password:f.get('password')});if(error)throw Error('تعذّر الدخول. تأكد من اسم المستخدم أو البريد وكلمة المرور ومن اتصالك.');const {data:role,error:roleError}=await db.from('qatta_admins').select('user_id').eq('user_id',data.user.id).maybeSingle();if(roleError||!role){await db.auth.signOut();throw Error('هذا الحساب غير مسجّل كمسؤول عن القطّة.');}admin=true;await refresh();render();closeDialog();toast('حيّ الله أمين القطّة!');});}
async function refresh(){if(!db)return;try{const {data,error}=await db.from('qatta_ledger').select('data,revision').eq('id','main').single();if(error)throw error;const next=validateState(data.data);next.demo=false;state=next;revision=data.revision;syncState='online';render();}catch{syncState='offline';render();throw Error('تعذّر تحميل السجل. راجع الاتصال وإعداد قاعدة البيانات.');}}
async function initializeCloud(){if(!configured)return;try{if(config.supabaseKey.includes('.')){let claims;try{claims=JSON.parse(atob(config.supabaseKey.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));}catch{throw Error('المفتاح غير صالح. استخدم Publishable أو anon.');}if(claims.role!=='anon')throw Error('استخدم المفتاح العلني فقط، وليس مفتاح خدمة خاص.');}if(!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/.test(config.supabaseUrl)||config.supabaseKey.startsWith('sb_secret_'))throw Error('راجع رابط Supabase واستخدم المفتاح العلني فقط.');if(!window.supabase?.createClient)throw Error('مكتبة الاتصال غير متوفرة.');db=window.supabase.createClient(config.supabaseUrl,config.supabaseKey,{auth:{persistSession:true,detectSessionInUrl:false}});const {data:{session}}=await db.auth.getSession();if(session){const {data:role}=await db.from('qatta_admins').select('user_id').eq('user_id',session.user.id).maybeSingle();admin=Boolean(role);}await refresh();db.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){admin=false;render();}});}catch(e){syncState='offline';render();toast(e.message||'تعذّر الاتصال بالسجل.');}}
document.addEventListener('click',async event=>{const filterButton=event.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;render();return;}const link=event.target.closest('[data-section]');if(link){document.querySelectorAll('[data-section]').forEach(el=>el.classList.toggle('active',el===link));return;}const button=event.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;try{switch(action){case'close-dialog':closeDialog();break;case'payment':paymentDialog(id);break;case'member':memberDialog();break;case'expense':expenseDialog(id);break;case'settings':settingsDialog();break;case'months':monthsDialog();break;case'create-month':createMonthDialog();break;case'select-month':selectedMonth=button.dataset.month;filter='all';render();closeDialog();break;case'previous-month':case'next-month':{const d=new Date(`${selectedMonth}-15T12:00:00`);d.setMonth(d.getMonth()+(action==='next-month'?1:-1));const key=dateISO(d).slice(0,7);if(validMonth(key)){selectedMonth=key;filter='all';render();}break;}case'export':exportData();break;case'import':if(canEdit())$('#import-file').click();break;case'start':setupDialog();break;case'account':await accountDialog();break;case'copy-iban':{try{await navigator.clipboard.writeText('SA8780000644608016919054');toast('تم نسخ آيبان حمدان.');}catch{const input=$('#hamdan-iban');input.focus();input.select();toast('حدّدنا الآيبان؛ اضغط مطولًا واختر نسخ.');}break;}case'sync':if(configured){if(!db)await initializeCloud();else{await refresh();toast('السجل محدّث.');}}else setupDialog();break;case'remove-member':{if(!canEdit())return;const p=current().members.find(x=>x.id===id);if(p)confirmDialog('حذف الخوي من هذا الشهر',`سيُحذف ${p.name} ودفعتُه (${fmt(p.paid/100)} ر.س) من هذا الشهر فقط.`,()=>commit(d=>{d.months[selectedMonth].members=d.months[selectedMonth].members.filter(x=>x.id!==id);},'تم حذف الخوي من الشهر.'),'نعم، احذف');break;}case'remove-expense':{if(!canEdit())return;const e=current().expenses.find(x=>x.id===id);if(e)confirmDialog('حذف الالتزام',`سيُحذف «${e.title}» ويتحدث رصيد الصندوق.`,()=>commit(d=>{d.months[selectedMonth].expenses=d.months[selectedMonth].expenses.filter(x=>x.id!==id);},'تم حذف الالتزام.'),'نعم، احذف');break;}}}catch(e){toast(e.message||'تعذّر تنفيذ الطلب.');}});
$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file||!canEdit())return;try{if(file.size>1500000)throw Error('الملف أكبر من الحد المسموح (١٫٥ ميجابايت).');const imported=validateState(JSON.parse(await file.text()));if(configured&&imported.demo)throw Error('هذه نسخة تجريبية؛ لا يمكن استيرادها إلى السجل الحقيقي.');confirmDialog('استبدال الدفتر بالنسخة',`ستستبدل جميع الشهور الحالية بنسخة «${imported.settings.name}» التي تحتوي ${fmt(Object.keys(imported.months).length)} شهرًا. احتفظ بنسخة حالية أولًا.`,async()=>{await commit(d=>{d.settings=imported.settings;d.months=imported.months;},'تم استيراد الدفتر.');},'استبدال الدفتر');}catch(e){toast(e instanceof SyntaxError?'الملف ليس نسخة JSON صالحة.':e.message);}});
$('#app-dialog').addEventListener('click',event=>{if(event.target===$('#app-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
setInterval(()=>{if(configured&&db&&!document.hidden&&!$('#app-dialog').open&&!saving)refresh().catch(()=>{});},30000);
document.addEventListener('visibilitychange',()=>{if(configured&&db&&!document.hidden&&!$('#app-dialog').open&&!saving)refresh().catch(()=>{});});
window.addEventListener('online',()=>{if(configured&&db&&!saving&&!$('#app-dialog').open)refresh().catch(()=>{});});
function registerAgentTools(){if(!document.modelContext?.registerTool)return;try{Promise.resolve(document.modelContext.registerTool({name:'read_qatta_month',title:'قراءة دفتر القطّة',description:'Read the selected month, amounts in Saudi halalas, members, and expenses without changing the ledger.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('No arguments are accepted.');return {month:selectedMonth,demo:state.demo,connection:syncState,totals:totals(),ledger:structuredClone(current()||null)};}})).catch(()=>{});}catch{/* WebMCP is optional. */}}
render();initializeCloud();registerAgentTools();
